def compute_tax_mig_step(quote: dict) -> dict:
    net_cents = int(quote['net_cents'])
    tax_cents = (net_cents * 1000) // 10000
    return {
        'tax_cents': tax_cents,
        'gross_collected_cents': net_cents + tax_cents,
        'step_1_state': 3,
        'step_1_representation_id': 'rep-v2',
        'step_1_obligations': [],
    }

